function levelsBottomUp(root: TreeNode | null): number[][] {
  const levels: number[][] = [];
  const stack: [TreeNode, number][] = root ? [[root, 0]] : [];
  while (stack.length) {
    const [node, d] = stack.pop()!;
    if (d === levels.length) levels.push([]);
    levels[d].push(node.val);
    // push right first so the left subtree is handled first
    if (node.right) stack.push([node.right, d + 1]);
    if (node.left) stack.push([node.left, d + 1]);
  }
  return levels.reverse();
}

