class Solution:
    def levelsBottomUp(self, root: Optional[TreeNode]) -> List[List[int]]:
        levels = []
        stack = [(root, 0)] if root else []
        while stack:
            node, d = stack.pop()
            if d == len(levels):
                levels.append([])
            levels[d].append(node.val)
            if node.right:
                stack.append((node.right, d + 1))
            if node.left:
                stack.append((node.left, d + 1))
        return levels[::-1]

